<?php require_once __DIR__.'/../config/config.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'');if(in_array($status,['new','contacted','confirmed','completed','cancelled'],true)){$s=$pdo->prepare('UPDATE bookings SET status=? WHERE id=?');$s->execute([$status,$id]);log_admin('booking.status','Booking #'.$id.' changed to '.$status);flash('notice','Booking status updated.');}header('Location: bookings.php');exit;}$pageTitle='Bookings';$active='bookings';$rows=$pdo->query('SELECT * FROM bookings ORDER BY created_at DESC LIMIT 500')->fetchAll();require __DIR__.'/_layout.php';?>
<section class="welcome-row"><div><p class="eyebrow">CLIENT ENQUIRIES</p><h1>Bookings & <em>events.</em></h1><p class="muted">Review enquiries, event details and update each booking status.</p></div><a class="btn btn-outline" href="export.php?table=bookings">Export CSV ↗</a></section><section class="panel"><div class="panel-head"><h2><?=count($rows)?> bookings</h2><input style="max-width:260px" type="search" placeholder="Search bookings…" data-search-table="#bookingsTable"></div><div class="table-wrap"><table id="bookingsTable"><thead><tr><th>CLIENT</th><th>SERVICE</th><th>EVENT DATE</th><th>BUDGET</th><th>STATUS</th><th>UPDATE</th></tr></thead><tbody><?php foreach($rows as $b):?><tr><td><b><?=e($b['name'])?></b><small><?=e($b['email'])?> · <?=e($b['phone']??'')?></small></td><td><?=e($b['service'])?></td><td><?=e($b['event_date']?:'—')?></td><td><?=isset($b['budget'])&&$b['budget']!==null?'₹'.number_format((float)$b['budget'],2):'—'?></td><td><span class="status <?=e($b['status'])?>"><?=e(ucfirst($b['status']))?></span></td><td><form class="inline-form" method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$b['id']?>"><select name="status"><?php foreach(['new','contacted','confirmed','completed','cancelled'] as $status):?><option value="<?=$status?>" <?=$b['status']===$status?'selected':''?>><?=ucfirst($status)?></option><?php endforeach;?></select><button class="btn btn-small">Save</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="empty">No booking enquiries yet.</td></tr><?php endif;?></tbody></table></div></section><?php require __DIR__.'/_footer.php';?>
